const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs/promises'),path=require('node:path'),os=require('node:os'),{randomUUID}=require('node:crypto');
const build=process.env.AGENTOPIA_COMPOSIO_TEST_BUILD,resources=process.env.AGENTOPIA_COMPOSIO_NATIVE_RESOURCES;
if(!build||!resources)throw Error('Run the isolated native Composio qualification.');
const {fixture}=require('./composio.cjs'),{CodexHarness}=require(path.join(build,'codex-harness.js')),{ToolService}=require(path.join(build,'tool-service.js')),{RemoteTools}=require(path.join(build,'remote-tools.js')),{Broker}=require(path.join(build,'broker.js'));

function database(f){const tables={agents:[{id:f.agent,user_id:f.owner,active:true,metadata:{}}]};return {tables,from(name){const rows=tables[name]??=[];let filters=[],insert,update,done=false;const value=(row,key)=>key.includes('->>')?row[key.split('->>')[0]]?.[key.split('->>')[1]]:row[key];const perform=()=>{if(insert&&!done){rows.push(...structuredClone(Array.isArray(insert)?insert:[insert]));done=true;}const selected=rows.filter(row=>filters.every(match=>match(row)));if(update&&!done){selected.forEach(row=>Object.assign(row,structuredClone(update)));done=true;}return {data:selected,error:null};};const q={select(){return q;},eq(k,v){filters.push(row=>value(row,k)===v);return q;},neq(k,v){filters.push(row=>value(row,k)!==v);return q;},is(k,v){filters.push(row=>v===null?value(row,k)==null:value(row,k)===v);return q;},in(k,v){filters.push(row=>v.includes(value(row,k)));return q;},order(){return q;},range(){return q;},limit(){return q;},insert(v){insert=v;return q;},update(v){update=v;return q;},single:async()=>({data:perform().data[0]??null,error:null}),maybeSingle:async()=>({data:perform().data[0]??null,error:null}),then(resolve,reject){return Promise.resolve(perform()).then(resolve,reject);}};return q;}};}
function nativeResponse(item){const response={id:'response-'+randomUUID(),object:'response',status:'completed',output:[item],usage:{input_tokens:1,output_tokens:1,total_tokens:2}};return new Response(['response.created','response.output_item.added','response.output_item.done','response.completed'].map(type=>'event: '+type+'\ndata: '+JSON.stringify({type,...(type==='response.created'?{response:{...response,status:'in_progress',output:[]}}:type==='response.completed'?{response}:{output_index:0,item})})+'\n\n').join(''),{headers:{'content-type':'text/event-stream'}});}
const complete=()=>nativeResponse({id:randomUUID(),type:'message',role:'assistant',status:'completed',content:[{type:'output_text',text:'CONTROLLED-COMPOSIO-FINISHED',annotations:[]}]});
function toolCall(body,name,args,id){
 function find(tools,namespace){for(const tool of tools??[]){if(tool.type==='namespace'){const found=find(tool.tools,tool.name);if(found)return found;}else if((tool.name??'').endsWith(name))return {...tool,namespace};}}
 const code=body.tools.find(tool=>tool.type==='custom'&&tool.name==='exec'),direct=find(body.tools),nested=code?.description?.match(new RegExp('declare const tools: \\{ ([A-Za-z0-9_]*'+name+')\\('));
 if(nested||code?.description?.includes('ALL_TOOLS'))return nativeResponse({id,call_id:id,type:'custom_tool_call',name:'exec',input:nested?'text(await tools.'+nested[1]+'('+JSON.stringify(args)+'));':'const tool=ALL_TOOLS.find(tool=>tool.name.endsWith('+JSON.stringify(name)+')); if(!tool)throw Error("Missing owned connector tool"); text(await tools[tool.name]('+JSON.stringify(args)+'));',status:'completed'});
 assert(direct,'The actual Codex catalog must expose '+name);return nativeResponse({id,call_id:id,type:'function_call',name:direct.name,...(direct.namespace?{namespace:direct.namespace}:{}),arguments:JSON.stringify(args),status:'completed'});
}
async function setup(run){
 const directory=await fs.mkdtemp(path.join(os.tmpdir(),'agentopia-composio-native-')),f=fixture(),connection=await f.connect(),db=database(f),events=[],user={id:f.owner,email:'controlled-composio@example.invalid',admin:true},saved={},realFetch=global.fetch;
 for(const [key,value]of Object.entries({USERPROFILE:directory,APPDATA:path.join(directory,'appdata'),LOCALAPPDATA:path.join(directory,'local')})){saved[key]=process.env[key];process.env[key]=value;}
 const remote=new RemoteTools(db);remote.composio=f.service;remote.plugins={ensure:async()=>{},search:async()=>({name:'serper-search',adapter:'serper',enabled:false}),managedChrome:async()=>{throw Error('Not assigned');}};
 const providers={harnessScope:provider=>'controlled-composio-'+provider,models:async()=>[{id:'gpt-6.1-sol'},{id:'openai/gpt-6.1-sol'}],token:async()=>'CONTROLLED-COMPOSIO-TOKEN'},harness=new CodexHarness(db,providers,directory,resources,(_,event)=>events.push(event),async()=>{},async()=>true),tools=new ToolService(db,{},(owner,event)=>{events.push(event);harness.toolEvent(owner,event);},async()=>user,remote,undefined,{definitions:()=>[],authorize:()=>{}});
 const receiver=Object.assign(Object.create(Broker.prototype),{workspaceMonitor:{generation:0},identity:async()=>user,composio:f.service,nativeControls:0,native:harness,backingUp:false});
 const options={permission:'full',mode:'chat',thinking:'default',files:[],tools:['mcp:'+connection.id]},actions=()=>f.calls.filter(row=>row.url.pathname.includes('/tools/execute/'));
 async function turn(provider,permission='full'){
  const request={id:randomUUID(),agent_id:f.agent,conversation_id:randomUUID(),user_message_id:randomUUID(),assistant_message_id:randomUUID()},activeOptions={...options,permission},plan=await remote.plan(f.owner,f.agent,activeOptions);(db.tables.conversation_sessions??=[]).push({conversation_id:request.conversation_id,user_id:f.owner,agent_id:f.agent});const rows=[{id:request.user_message_id,role:'user',content:{text:'Use my connected GitHub account to list repositories.'},metadata:{}},{id:request.assistant_message_id,role:'assistant',content:{text:''},metadata:{}}],controller=new AbortController(),timer=setTimeout(()=>controller.abort(new Error('Controlled native turn deadline')),45000);
  const pending=harness.run(user,request,{id:f.agent},provider,provider==='openrouter'?'openai/gpt-6.1-sol':'gpt-6.1-sol',activeOptions,[],rows,plan.definitions,(name,args,id,signal,threadId)=>tools.execute(user,request,{name,arguments:JSON.stringify(args),id},activeOptions,signal,plan,f.agent,threadId),controller).finally(()=>clearTimeout(timer));return {request,controller,pending};
 }
 try{await run({...f,directory,providers,connection,db,events,user,remote,harness,tools,receiver,options,actions,turn,setFetch:fn=>global.fetch=fn});}
 finally{await harness.close();global.fetch=realFetch;for(const [key,value]of Object.entries(saved))if(value===undefined)delete process.env[key];else process.env[key]=value;assert.equal(path.dirname(await fs.realpath(directory)),await fs.realpath(os.tmpdir()));await fs.rm(directory,{recursive:true,force:true,maxRetries:10,retryDelay:100});}
}
function controlled(f,final=true){let calls=0;f.observedRequests=[];f.setFetch(async(url,init)=>{assert(['https://api.openai.com/v1/responses','https://openrouter.ai/api/v1/responses'].includes(String(url)));assert.equal(init.headers.Authorization,'Bearer CONTROLLED-COMPOSIO-TOKEN');const body=JSON.parse(init.body);f.observedRequests.push(body);calls++;if(calls===1)return toolCall(body,'mcp_search',{query:'repository',connection_id:f.connection.id,cursor:0},'search-'+randomUUID());if(calls===2){assert(JSON.stringify(body.input).includes('GITHUB_LIST_REPOSITORIES'));return toolCall(body,'mcp_call',{connection_id:f.connection.id,tool_name:'GITHUB_LIST_REPOSITORIES',arguments_json:JSON.stringify({limit:5})},'call-'+randomUUID());}assert(final&&calls===3,'The controlled turn must stop without retrying');assert(JSON.stringify(body.input).includes('saved-result'));return complete();});return ()=>calls;}


module.exports={setup,controlled,toolCall,nativeResponse,complete,database};
